        this.addAnnotation((ENamedElement)this.transmissionModeTimingEClass, source, new String[]{"documentation", "If the COM Transmission Mode is false the timing is aggregated by the TransmissionModeTiming element in the role of transmissionModeFalseTiming. If the COM Transmission Mode is true the timing is aggregated by the TransmissionModeTiming element in the role of transmissionModeTrueTiming.  \r\n\r\nCOM supports the following Transmission Modes: \r\nPeriodic (Cyclic Timing)\r\nDirect /n-times (EventControlledTiming)\r\nMixed (Cyclic and EventControlledTiming are assigned)\r\nNone (no timing is assigned)"});
        this.addAnnotation((ENamedElement)this.getTransmissionModeTiming_CyclicTiming(), source, new String[]{"documentation", "Periodic Transmission Mode."});
